import React from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ConfigProvider } from 'antd';
import { App } from './App';

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: 1,
      refetchOnWindowFocus: false,
      staleTime: 30_000,
    },
  },
});

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <QueryClientProvider client={queryClient}>
      <ConfigProvider>
        <BrowserRouter basename="/portal">
          <App />
        </BrowserRouter>
      </ConfigProvider>
    </QueryClientProvider>
  </React.StrictMode>,
);

import { useQuery } from '@tanstack/react-query';
import { Table, Tag, Empty, Skeleton } from 'antd';
import type { TableProps } from 'antd';
import { PageContainer } from '@/components/PageContainer';
import type { PageState } from '@/components/PageContainer';
import { apiClient } from '@/api/client';
import type { DocumentListResponse, Document } from '@/types/models';

const documentColumns: TableProps<Document>['columns'] = [
  {
    title: '文档类型',
    dataIndex: 'documentType',
    key: 'documentType',
    width: 140,
    render: (value: string, record: Document) => (
      <Tag data-testid={`document-type-${record.documentId}`}>{value}</Tag>
    ),
  },
  {
    title: '描述',
    dataIndex: 'description',
    key: 'description',
  },
  {
    title: '创建时间',
    dataIndex: 'createdDate',
    key: 'createdDate',
    width: 180,
  },
  {
    title: '操作',
    key: 'action',
    width: 100,
    render: (_: unknown, record: Document) => (
      <a
        href={`/api/customer/v1/documents/${record.documentId}/download`}
        data-testid={`document-download-${record.documentId}`}
      >
        下载
      </a>
    ),
  },
];

export function Documents(): JSX.Element {
  const { data, isLoading, isError } = useQuery<DocumentListResponse>({
    queryKey: ['documents'],
    queryFn: () => apiClient.get<DocumentListResponse>('/documents'),
  });

  const pageState: PageState = isLoading
    ? 'LOADING'
    : isError
      ? 'ERROR'
      : 'READY';

  const documents = data?.items ?? [];

  return (
    <PageContainer
      pageId="customer.documents"
      state={pageState}
      title="文档"
    >
      <div data-testid="document-list" style={{ padding: '24px' }}>
        {isLoading && <Skeleton active />}

{!isLoading && isError && (
          <Empty description="加载文档列表失败" data-testid="document-list-error" />
        )}

        {!isLoading && !isError && documents.length === 0 && (
          <Empty description="暂无文档" data-testid="document-list-empty" />
        )}

        {!isLoading && !isError && documents.length > 0 && (
          <Table
            columns={documentColumns}
            dataSource={documents}
            rowKey="documentId"
            pagination={{ pageSize: 10 }}
            data-testid="document-list-table"
          />
        )}
      </div>
    </PageContainer>
  );
}

import { useQuery } from '@tanstack/react-query';
import { Card, Descriptions, Tag, Skeleton, Empty } from 'antd';
import { PageContainer } from '@/components/PageContainer';
import type { PageState } from '@/components/PageContainer';
import { apiClient } from '@/api/client';
import type { SecuritySettingsResponse } from '@/types/models';

export function SecuritySettings(): JSX.Element {
  const { data, isLoading, isError } = useQuery<SecuritySettingsResponse>({
    queryKey: ['security-settings'],
    queryFn: () => apiClient.get<SecuritySettingsResponse>('/security/settings'),
  });

  const pageState: PageState = isLoading
    ? 'LOADING'
    : isError
      ? 'ERROR'
      : 'READY';

  return (
    <PageContainer
      pageId="customer.security"
      state={pageState}
      title="安全设置"
    >
      <div data-testid="security-settings" style={{ padding: '24px' }}>
        {isLoading && <Skeleton active />}

        {!isLoading && isError && (
          <Empty description="加载安全设置失败" data-testid="security-settings-error" />
        )}

        {!isLoading && !isError && data === undefined && (
          <Empty description="未找到安全设置" data-testid="security-settings-empty" />
        )}

        {data !== undefined && (
          <Card>
            <Descriptions bordered column={1}>
              <Descriptions.Item label="多因素认证 (MFA)">
                {data.mfaEnabled ? (
                  <Tag color="green" data-testid="security-mfa-enabled">
                    已启用
                  </Tag>
                ) : (
                  <Tag color="red" data-testid="security-mfa-disabled">
                    未启用
                  </Tag>
                )}
              </Descriptions.Item>
              {data.mfaMethod !== undefined && (
                <Descriptions.Item label="MFA方式">
                  <span data-testid="security-mfa-method">{data.mfaMethod}</span>
                </Descriptions.Item>
              )}
              {data.lastPasswordChange !== undefined && (
                <Descriptions.Item label="上次密码修改">
                  <span data-testid="security-password-change">
                    {data.lastPasswordChange}
                  </span>
                </Descriptions.Item>
              )}
              <Descriptions.Item label="登录通知">
                {data.loginNotificationsEnabled ? (
                  <Tag color="green" data-testid="security-login-notify-on">
                    已开启
                  </Tag>
                ) : (
                  <Tag color="default" data-testid="security-login-notify-off">
                    未开启
                  </Tag>
                )}
              </Descriptions.Item>
              {data.lastLoginAt !== undefined && (
                <Descriptions.Item label="上次登录时间">
                  <span data-testid="security-last-login">{data.lastLoginAt}</span>
                </Descriptions.Item>
              )}
            </Descriptions>
          </Card>
        )}
      </div>
    </PageContainer
>
  );
}

import type { Resolver, FieldErrors as RhfFieldErrors } from 'react-hook-form';
import type { z } from 'zod';

export function zodResolver<T extends z.ZodType>(
  schema: T,
): Resolver<z.infer<T>> {
  return async (values) => {
    const result = await schema.safeParseAsync(values);
    if (result.success) {
      return {
        values: result.data,
        errors: {},
      };
    }
    const errors: Record<string, { type: string; message: string }> = {};
    for (const issue of result.error.issues) {
      const path = issue.path.join('.');
      if (!errors[path]) {
        errors[path] = {
          type: issue.code,
          message: issue.message,
        };
      }
    }
    return {
      values: {},
      errors: errors as unknown as RhfFieldErrors<z.infer<T>>,
    };
  };
}

